<script>
  import { toStyleString } from '@splendidlabz/utils'
  export let color
  export let top
  export let bottom

  let style

  if (!top && !bottom) {
    style = 'background-color: var(--color);'
  }

  if (top && bottom) {
    style = toStyleString({
      'line-height': 1,
      'background-image': `linear-gradient(
        transparent ${top},
        var(--color) ${top},
        var(--color) ${bottom},
        transparent ${bottom}
      )`,
    })
  }
</script>

<!-- Remove space after <slot/> to ensure there's no extra whitespace -->
<span class="Highlight" {color} {style}><slot /></span>
